{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, had an absolute oral bioavailability of only 0.5–1% in healthy subjects after 400 mg oral dosing, directly demonstrating that sulfated carbohydrate structures are very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dextran sulfate, another highly sulfated carbohydrate, is reported to have poor oral bioavailability in humans, supporting the same conclusion for sulfated sugar-based molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zanamivir, a polar carbohydrate-like drug with carboxylic acid and multiple hydroxyls, had an absolute oral bioavailability of 2% (range 1–5%) in volunteers, directly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate, a small zwitterionic sulfonate, had an absolute oral bioavailability of 11 ± 1% in healthy volunteers, still below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a glucosinolate containing a glucose moiety and sulfonate, had a median oral bioavailability of 5% (range 1–45%) in 50 participants, directly below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "N-acetylcysteine, a small polar amino acid derivative, had oral bioavailability of 4–10% in humans across multiple studies, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "One older report estimated oral acetylcysteine bioavailability at ~80%, but this is an outlier contradicted by multiple direct i.v.-comparison studies in healthy subjects (4–10%) and is not supported by the physicochemical properties of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, sulfated/carboxylated carbohydrate-like molecule. Direct human absolute bioavailability measurements for closely related sulfated polysaccharides (pentosan polysulfate 0.5–1%, dextran sulfate poor) and polar carbohydrate/sulfonate drugs (zanamivir 2%, acamprosate 11%, glucoraphanin 5%, N-acetylcysteine 4–10%) all fall below 20%, with high assay-transfer scores. The physicochemical prior also predicts negligible permeability. A single older report of ~80% for acetylcysteine is an outlier and does not outweigh the consistent low-F evidence. Therefore F ≥20% is not supported; prediction is low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query disaccharide; extrapolation relies on close analogues.",
    "The query's potential as a substrate for intestinal transporters or prodrug strategies is not experimentally characterized.",
    "One older report of ~80% oral bioavailability for acetylcysteine is inconsistent with direct comparative studies and remains unresolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

